package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.QuoteModels.*;import com.ferreteriahuaman.dto.CatalogModels.Page;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.annotation.Isolation;
@Service @Profile("db") public class QuoteService {
 private final QuoteRepository repo;private final BusinessTransactions tx;private final CashRepository cash;private final AuthStore auth;private final ObjectMapper mapper;
 public QuoteService(QuoteRepository repo,BusinessTransactions tx,CashRepository cash,AuthStore auth,ObjectMapper mapper){this.repo=repo;this.tx=tx;this.cash=cash;this.auth=auth;this.mapper=mapper;}
 private String json(Object o){if(o==null)return null;try{return mapper.writeValueAsString(o);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("No se pudo preparar la cotización");}}
 private Map<String,Object> owned(Identity a,long id,boolean lock){var c=repo.get(id,lock).orElseThrow(()->new AuthFailure(404,"Cotización no encontrada"));boolean admin=lock?auth.lockUser(a.id()).map(u->u.rol().equals("ADM")).orElse(false):a.rol().equals("ADM");if(((Number)c.get("vendedorId")).longValue()!=a.id()&&!admin)throw new AuthFailure(403,"Solo puedes gestionar tus propias cotizaciones");return c;}
 private void version(Map<String,Object> c,LocalDateTime v){if(v==null)throw new AuthFailure(400,"Falta la versión de la cotización");if(!LocalDateTime.parse(c.get("version").toString()).equals(v))throw new AuthFailure(409,"La cotización cambió. Vuelve a cargarla antes de continuar");}
 private void draft(Map<String,Object> c){if(!c.get("estado").equals("BORRADOR")||!c.get("fecha").equals(c.get("hoy")))throw new AuthFailure(409,"Solo se edita un borrador de hoy. Copia una cotización antigua para preparar otra");}
 public Page<Map<String,Object>> list(Identity a,String q,String state,LocalDate start,LocalDate end,int page,int size){if(q.length()>100||!Set.of("","BORRADOR","VIGENTE","VENCIDA","CONVERTIDA","ANULADA").contains(state)||page<0||page>1000000||size<1||size>100||start!=null&&end!=null&&start.isAfter(end))throw new AuthFailure(400,"Revisa los filtros y la paginación");return repo.list(a.id(),a.rol().equals("ADM"),q.strip(),state,start,end,page,size);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Details details(Identity a,long id){return new Details(owned(a,id,false),repo.lines(id));}
 public Map<String,Object> options(){var c=cash.current();var result=new LinkedHashMap<String,Object>();result.put("hoy",c.fechaServidor());result.put("vigenciaDias",repo.days());result.put("caja",c.caja()==null?null:Map.of("id",c.caja().id(),"fecha",c.caja().fecha(),"estado",c.caja().estado()));return result;}
 public Details save(Identity a,String pc,Long id,Save i){return tx.write(a,pc,"COC.COTIZAR",()->{repo.lock(i.clave());String request=json(Map.of("id",id==null?0:id,"datos",i));var replay=repo.replay(a.id(),"COC.GUARDAR_API",i.clave(),request);if(replay.isPresent())return details(a,replay.get());var seen=new HashSet<Long>();for(var l:i.lineas())if(!seen.add(l.presentacionId()))throw new AuthFailure(400,"Agrupa la cantidad de una misma presentación en una sola línea");Details before=null;long saved;if(id==null)saved=repo.create(a.id(),i);else{var c=owned(a,id,true);version(c,i.version());draft(c);before=new Details(c,repo.lines(id));repo.update(id,i);saved=id;}repo.replace(saved,i.lineas());var after=details(a,saved);repo.audit(a.id(),"COC.GUARDAR_API",saved,i.clave(),request,saved,json(before),json(after));return after;});}
 public Details action(Identity a,String pc,long id,String action,Action i){return tx.write(a,pc,"COC.COTIZAR",()->{if(!Set.of("emitir","anular","recalcular","copiar","imprimir").contains(action))throw new AuthFailure(404,"Operación no encontrada");repo.lock(i.clave());String name="COC."+action.toUpperCase(Locale.ROOT)+"_API",request=json(Map.of("id",id,"datos",i));var replay=repo.replay(a.id(),name,i.clave(),request);if(replay.isPresent())return details(a,replay.get());var c=owned(a,id,true);version(c,i.version());if(((Number)c.get("revision")).intValue()!=i.revision())throw new AuthFailure(409,"La revisión cambió. Vuelve a cargar la cotización");var before=new Details(c,repo.lines(id));long result=id;switch(action){case "emitir"->repo.emit(id,i.clave());case "anular"->{if(i.motivo()==null||i.motivo().strip().length()<10)throw new AuthFailure(400,"Explica el motivo de anulación con al menos diez caracteres");repo.cancel(id,i.clave(),i.motivo());}case "recalcular"->repo.recalculate(id,i.revision(),i.clave());case "copiar"->{var lines=before.lineas().stream().map(l->new Line(((Number)l.get("presentacionId")).longValue(),new BigDecimal(l.get("cantidad").toString()))).toList();if(lines.isEmpty())throw new AuthFailure(409,"La cotización no tiene productos para copiar");var input=new Save((Long)c.get("clienteId"),(String)c.get("interesado"),(String)c.get("observacion"),i.clave(),null,lines);result=repo.create(a.id(),input);repo.replace(result,lines);}}
 var after=details(a,result);repo.audit(a.id(),name,id,i.clave(),request,result,json(before),json(after));return after;});}
 public Conversion convert(Identity a,String pc,long id,Convert i){return tx.write(a,pc,"COC.COTIZAR",()->{if(!auth.permissions(a.id()).contains("VEN.VENDER"))throw new AuthFailure(403,"Necesitas permiso para preparar ventas");repo.lock(i.clave());String request=json(Map.of("id",id,"datos",i));var replay=repo.replay(a.id(),"COC.CONVERTIR_API",i.clave(),request);if(replay.isPresent()){owned(a,id,false);return new Conversion(replay.get());}var current=cash.current();if(current.caja()==null||!current.caja().estado().equals("ABIERTA")||!current.caja().fecha().equals(current.fechaServidor()))throw new AuthFailure(409,"Abre la caja de hoy antes de convertir la cotización");repo.lockCash(current.caja().id());var c=owned(a,id,true);version(c,i.version());long sale=repo.convert(id,current.caja().id(),i.tipo(),i.clave());repo.audit(a.id(),"COC.CONVERTIR_API",id,i.clave(),request,sale,null,json(details(a,id)));return new Conversion(sale);});}

}
